package mz.bam.seeky.android;
import android.content.*;import android.database.sqlite.SQLiteDatabase;import java.io.IOException;import java.util.UUID;
/** Durable timer transitions. A unique session token makes crash recovery idempotent. */
final class FocusSessions {
 static final Object LOCK=new Object();
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("studies",0);}
 static long seconds(SharedPreferences p,long elapsed,long wall){return FocusClock.seconds(p.getBoolean("timer_paused",false),p.getLong("timer_acc",0),p.getLong("timer_limit",1500),elapsed,p.getLong("timer_elapsed",0),wall,p.getLong("timer_wall",0));}
 static boolean matches(SharedPreferences p,String token){return token==null||token.equals(p.getString("timer_token",""));}
 static void dirty(Context c){try{StudyState.bump(c);}catch(Exception e){AppDiagnostics.record(c,"timer-backup-state",e);}}
 static void start(Context c,String goal,long subject,int minutes,String type,long elapsed,long wall)throws Exception{synchronized(LOCK){SharedPreferences p=prefs(c);if(p.getBoolean("timer_active",false))throw new IllegalStateException("Já existe uma sessão em curso.");String title=StudySchedule.valid(goal,240,"Objectivo");if(minutes<1||minutes>120||!(type.equals("Foco")||type.equals("Pausa")))throw new IllegalArgumentException("Duração inválida.");try(StudyStore db=new StudyStore(c)){if(subject>0&&db.get("subjects",subject)==null)throw new IllegalArgumentException("Módulo indisponível.");}if(!p.edit().putBoolean("timer_active",true).putBoolean("timer_paused",false).putLong("timer_acc",0).putLong("timer_limit",minutes*60L).putLong("timer_elapsed",elapsed).putLong("timer_wall",wall).putLong("timer_started",wall).putLong("timer_subject",subject).putString("timer_goal",title).putString("timer_type",type).putString("timer_token",UUID.randomUUID().toString()).remove("timer_warning").commit())throw new IOException("Não foi possível guardar o temporizador.");dirty(c);}}
 static void toggle(Context c,String expected,long elapsed,long wall)throws Exception{synchronized(LOCK){SharedPreferences p=prefs(c);if(!p.getBoolean("timer_active",false)||!matches(p,expected))return;long value=seconds(p,elapsed,wall);if(!p.edit().putLong("timer_acc",value).putBoolean("timer_paused",!p.getBoolean("timer_paused",false)).putLong("timer_elapsed",elapsed).putLong("timer_wall",wall).commit())throw new IOException("Não foi possível guardar a pausa.");dirty(c);}}
 static final class Result {final long seconds;final boolean changed,recorded;Result(long s,boolean c,boolean r){seconds=s;changed=c;recorded=r;}}
 static Result finish(Context c,String expected,boolean discard,long elapsed,long wall)throws Exception{synchronized(LOCK){SharedPreferences p=prefs(c);if(!p.getBoolean("timer_active",false)||!matches(p,expected))return new Result(0,false,false);String token=p.getString("timer_token","");long seconds=seconds(p,elapsed,wall);boolean added=false;if(!discard&&seconds>0){try(StudyStore db=new StudyStore(c)){SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{if(db.count("sessions","token=?",new String[]{token})==0){long subject=p.getLong("timer_subject",0);if(subject>0&&db.get("subjects",subject)==null)subject=0;db.save("sessions",0,StudyStore.values("subject",subject,"started",p.getLong("timer_started",wall),"seconds",seconds,"goal",p.getString("timer_goal",""),"type",p.getString("timer_type","Foco"),"token",token));added=true;}sql.setTransactionSuccessful();}finally{sql.endTransaction();}}}if(!p.edit().putBoolean("timer_active",false).putBoolean("timer_paused",false).putLong("timer_acc",seconds).remove("timer_warning").commit())throw new IOException("Tempo registado; a sessão será reconciliada ao retomar.");dirty(c);return new Result(seconds,true,added);}}
}
